<body>
    <header>
        <div class="container header-content">
            <div class="logo">
                <i class="fas fa-chart-line"></i>
                <span>Dashboard Pro</span>
            </div>
            <nav>
                <ul>
                    <li><a href="#"><i class="fas fa-home"></i> Home</a></li>
                    <li><a href="#"><i class="fas fa-users"></i> Users</a></li>
                    <li><a href="#"><i class="fas fa-cog"></i> Settings</a></li>
                    <li><a href="#"><i class="fas fa-question-circle"></i> Help</a></li>
                </ul>
            </nav>
        </div>
    </header>

    <div class="container main-content">
        <h1 class="section-title">Dashboard Overview</h1>

        <div class="stats-container">
            <div class="stat-card">
                <i class="fas fa-users fa-2x"></i>
                <div class="stat-value" id="user-count">1,248</div>
                <div class="stat-label">Total Users</div>
            </div>
            <div class="stat-card">
                <i class="fas fa-shopping-cart fa-2x"></i>
                <div class="stat-value" id="order-count">362</div>
                <div class="stat-label">Orders</div>
            </div>
            <div class="stat-card">
                <i class="fas fa-dollar-sign fa-2x"></i>
                <div class="stat-value" id="revenue">$42,560</div>
                <div class="stat-label">Revenue</div>
            </div>
        </div>

        <div class="card-grid">
            <div class="card">
                <div class="card-header">
                    <h2 class="card-title">User Registration</h2>
                    <button class="btn btn-outline"><i class="fas fa-sync"></i> Refresh</button>
                </div>
                <form id="user-form">
                    <div class="form-group">
                        <label for="name">Full Name</label>
                        <input type="text" id="name" class="form-control" placeholder="Enter your name">
                    </div>
                    <div class="form-group">
                        <label for="email">Email Address</label>
                        <input type="email" id="email" class="form-control" placeholder="Enter your email">
                    </div>
                    <div class="form-group">
                        <label for="role">Role</label>
                        <select id="role" class="form-control">
                            <option value="user">User</option>
                            <option value="admin">Administrator</option>
                            <option value="editor">Editor</option>
                        </select>
                    </div>
                    <button type="submit" class="btn btn-primary"><i class="fas fa-user-plus"></i> Add User</button>
                </form>
            </div>

            <div class="card">
                <div class="card-header">
                    <h2 class="card-title">Data Visualization</h2>
                    <button class="btn btn-outline" id="fetch-data-btn"><i class="fas fa-download"></i> Fetch Data</button>
                </div>
                <div class="form-group">
                    <label for="data-filter">Filter by Status</label>
                    <select id="data-filter" class="form-control">
                        <option value="all">All Statuses</option>
                        <option value="active">Active</option>
                        <option value="pending">Pending</option>
                        <option value="inactive">Inactive</option>
                    </select>
                </div>
                <div class="form-group">
                    <label for="search-input">Search Data</label>
                    <input type="text" id="search-input" class="form-control" placeholder="Search...">
